#!/usr/bin/env python3
"""immuno/tcr_pmhc_dock — auto-generated run.py (archetype=docking).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "docking"
BRAIN = "immuno"
SKILL = "tcr_pmhc_dock"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'complex_pdb_path': 'runs/.../complex.pdb', 'interface_rmsd_to_ref': 1.85, 'cdr3_loop_clusters': [{'cluster': 1, 'rmsd_within': 0.8, 'members': 3}], 'iptm': 0.74, 'ptm': 0.69, 'plddt_mean': 78.0, 'pae_interface': 6.8, 'mhc_restriction_class': 'HLA_I', 'specificity_score': 0.82, 'qc_pass': True})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """TCR-pMHC docking via boltz/chai-lab(host_env=af2 改为 praxis-protein/boltz)。
    输入:tcr_alpha + tcr_beta + peptide + mhc_allele (或直接 fasta_input)
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    fasta = payload.get("fasta_input") or payload.get("yaml_input")
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="tcr_pmhc_")
    backend = payload.get("backend", "boltz")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "backend": backend, "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "receptor": "", "ligand": "", "best_affinity": 0.0,
                "poses": [{"rank": 1, "affinity_kcal_per_mol": 0.0, "pose_path": ""}],
                "runtime_sec": 0.0, "diagnostics": {**diagnostics, "dry": True}}
    if not fasta or not _os.path.isfile(fasta):
        return {"ok": False, "error": "需要 fasta_input (4 chains: TCRa/TCRb/peptide/MHC)",
                "diagnostics": diagnostics}
    if backend == "chai":
        cmd = ["chai-lab", "fold", fasta, out_dir]
    else:
        cmd = ["boltz", "predict", fasta, "--out_dir", out_dir,
               "--output_format", "pdb", "--use_msa_server"]
    t0 = _time.time()
    r = run_tool(cmd, timeout=int(payload.get("timeout_s", 3600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", f"{backend} 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    import glob as _glob
    pdbs = sorted(_glob.glob(_os.path.join(out_dir, "**", "*.pdb"), recursive=True))
    return {"ok": True, "skill_id": SKILL,
            "receptor": fasta, "ligand": "pMHC",
            "best_affinity": 0.0,
            "poses": [{"rank": i+1, "affinity_kcal_per_mol": 0.0, "pose_path": p} for i, p in enumerate(pdbs[:9])],
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
